function getStorageKey() {
    const t = window.CloudDB && window.CloudDB.getCurrentTenant();
    return t ? `RESPAWN_OS_DB_3.5_${t.id}` : _K;
}

let db = null;
try {
    db = JSON.parse(localStorage.getItem(getStorageKey())) || JSON.parse(localStorage.getItem(_K));
} catch(e) {}

if(!db||!db.categories)db=JSON.parse(JSON.stringify(_D));
if(db.menuVersion!==_V){
    db.categories=JSON.parse(JSON.stringify(_D.categories));
    db.menu=JSON.parse(JSON.stringify(_D.menu));
    db.menuVersion=_V;
    saveDB();
}

window.getAppDbState = function() {
    return db;
};

window.applyCloudUpdate = function(cloudData) {
    if (!cloudData || !cloudData.categories) return;

    // Preserve running timers locally
    if (db && db.tables && cloudData.tables) {
        Object.keys(cloudData.tables).forEach(tid => {
            const remoteTbl = cloudData.tables[tid];
            const localTbl = db.tables[tid];
            if (localTbl && localTbl.items && remoteTbl.items) {
                remoteTbl.items.forEach((rItem, idx) => {
                    const lItem = localTbl.items[idx];
                    if (lItem && lItem.isTime && lItem.isRunning && lItem.startTime) {
                        rItem.isRunning = true;
                        rItem.startTime = lItem.startTime;
                        rItem.elapsedSeconds = lItem.elapsedSeconds;
                    }
                });
            }
        });
    }

    db = cloudData;
    localStorage.setItem(getStorageKey(), JSON.stringify(db));
    if (window.updateDashboardStats) window.updateDashboardStats();
    if (window.switchView && window.uiState) window.switchView(window.uiState.currentView);
};

function saveDB(immediate = false){
    localStorage.setItem(getStorageKey(), JSON.stringify(db));
    if (window.CloudDB && typeof window.CloudDB.save === 'function') {
        window.CloudDB.save(db, immediate);
    }
}

window.AudioEngine={ctx:null,init(){if(!this.ctx)this.ctx=new(window.AudioContext||window.webkitAudioContext)();},play(t){try{this.init();const n=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.connect(g);g.connect(this.ctx.destination);if(t==='click'){o.frequency.setValueAtTime(800,n);g.gain.setValueAtTime(0.03,n);g.gain.exponentialRampToValueAtTime(0.001,n+0.04);o.start(n);o.stop(n+0.04);}else if(t==='success'){o.frequency.setValueAtTime(523.25,n);o.frequency.setValueAtTime(659.25,n+0.07);o.frequency.setValueAtTime(783.99,n+0.14);g.gain.setValueAtTime(0.08,n);g.gain.exponentialRampToValueAtTime(0.001,n+0.28);o.start(n);o.stop(n+0.28);}else if(t==='error'){o.type='square';o.frequency.setValueAtTime(200,n);g.gain.setValueAtTime(0.08,n);g.gain.exponentialRampToValueAtTime(0.001,n+0.2);o.start(n);o.stop(n+0.2);}}catch(e){}}};

window.showToast=(m,t='success')=>{
    const c=document.getElementById('toast-container');
    if(!c) return;
    const el=document.createElement('div');
    const cl=t==='success'?'border-emeraldGlow text-emeraldGlow bg-emeraldGlow/10':t==='error'?'border-roseAlert text-roseAlert bg-roseAlert/10':'border-cyanGlow text-cyanGlow bg-cyanGlow/10';
    el.className=`flex items-center gap-3 px-5 py-3.5 rounded-2xl glass-card border backdrop-blur-xl shadow-2xl text-xs font-bold animate__animated animate__fadeInDown animate__faster ${cl}`;
    el.innerHTML=`<span>${t==='success'?'✓':t==='error'?'✕':'ℹ'}</span><span>${m}</span>`;
    c.appendChild(el);
    setTimeout(()=>{el.classList.replace('animate__fadeInDown','animate__fadeOutUp');setTimeout(()=>el.remove(),400);},3000);
};

